// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testRegression_property() public {
        address killer = address(new Killer());

        vm.deal(address(c), 1 ether);

        c.forward(killer, abi.encodeWithSignature("kill()"));

        assertTrue(address(c).balance == 1 ether);
    }
}

contract Killer {
    function kill() public {
        selfdestruct(payable(msg.sender));
    }
}
